from collections import defaultdict

def at_most_k_distinct(nums: list[int], k: int) -> int:
    if k < 0:
        return 0
    freq: dict[int, int] = defaultdict(int)
    left = 0
    total = 0
    for right, val in enumerate(nums):
        freq[val] += 1
        while len(freq) > k:
            left_val = nums[left]
            freq[left_val] -= 1
            if freq[left_val] == 0:
                del freq[left_val]
            left += 1
        total += right - left + 1
    return total

def exact_k_distinct(nums: list[int], k: int) -> int:
    return at_most_k_distinct(nums, k) - at_most_k_distinct(nums, k - 1)

def longest_ones_with_k_flips(bits: list[int], k: int) -> int:
    left = zeros = best = 0
    for right, b in enumerate(bits):
        zeros += (b == 0)
        while zeros > k:
            zeros -= (bits[left] == 0)
            left += 1
        best = max(best, right - left + 1)
    return best

# 1) হাতে কষা উদাহরণ ও Brute-Force Oracle যাচাই
sample = [1, 2, 1, 2, 3]
assert exact_k_distinct(sample, 2) == 7
assert exact_k_distinct(sample, 0) == 0

stream = [3, 1, 2, 1, 3, 3, 4, 2, 1, 2]
for k_test in [1, 2, 3, 4]:
    brute = sum(
        len(set(stream[i : j + 1])) == k_test
        for i in range(len(stream))
        for j in range(i, len(stream))
    )
    assert exact_k_distinct(stream, k_test) == brute

# 2) Longest Window Invariant যাচাই
bits = [1, 1, 0, 0, 1, 1, 1, 0, 1, 1]
assert longest_ones_with_k_flips(bits, 2) == 7
print(f"exact_k(sample, 2)={exact_k_distinct(sample, 2)}, stream_k3={exact_k_distinct(stream, 3)}, max_span={longest_ones_with_k_flips(bits, 2)}")

class TrieNode:
    __slots__ = ("children", "freq", "is_end", "top_k")

    def __init__(self) -> None:
        self.children: dict[str, TrieNode] = {}
        self.freq: int = 0
        self.is_end: bool = False
        self.top_k: list[tuple[int, str]] = []  # (freq, word)

class AutocompleteTrie:
    def __init__(self, k: int = 3) -> None:
        self.root = TrieNode()
        self.k = k

    def update(self, word: str, delta: int = 1) -> None:
        if not word or delta <= 0:
            return
        node = self.root
        path = [node]
        for ch in word:
            if ch not in node.children:
                node.children[ch] = TrieNode()
            node = node.children[ch]
            path.append(node)
        node.is_end = True
        node.freq += delta
        total_freq = node.freq

        for anc in path:
            filtered = [(f, w) for f, w in anc.top_k if w != word]
            filtered.append((total_freq, word))
            filtered.sort(key=lambda item: (-item[0], item[1]))
            anc.top_k = filtered[: self.k]

    def query(self, prefix: str) -> list[str]:
        node = self.root
        for ch in prefix:
            if ch not in node.children:
                return []
            node = node.children[ch]
        return [w for _, w in node.top_k]

    def longest_prefix_tokenize(self, text: str) -> list[str]:
        tokens: list[str] = []
        i, n = 0, len(text)
        while i < n:
            node = self.root
            last_end = -1
            for j in range(i, n):
                ch = text[j]
                if ch not in node.children:
                    break
                node = node.children[ch]
                if node.is_end:
                    last_end = j + 1
            if last_end != -1:
                tokens.append(text[i:last_end])
                i = last_end
            else:
                tokens.append(text[i])
                i += 1
        return tokens

trie = AutocompleteTrie(k=2)
for w, f in [("mlops", 45), ("mlp", 30), ("mle", 60), ("ml_system", 60), ("matrix", 25)]:
    trie.update(w, f)
assert trie.query("ml") == ["ml_system", "mle"]
trie.update("mlp", 35)  # mlp মোট 65 হয়ে শীর্ষে উঠবে!
assert trie.query("ml") == ["mlp", "ml_system"]
assert trie.query("mlo") == ["mlops"]
assert trie.query("xyz") == []

# Greedy Longest-Prefix ম্যাচিং যাচাই
trie.update("ml_system_design", 10)
matched = trie.longest_prefix_tokenize("ml_system_design+mle")
assert matched == ["ml_system_design", "+", "mle"]
print(f"top2('ml')={trie.query('ml')}, tokens={matched}")
